-- Synthetic SQLite export from unchanged pre-Task-8 commit aeb5f9f87984b2a82791f5f9b34ea1f24740dd31.
-- All content/IDs are disposable test data; no model, transport or account calls.
CREATE TABLE active_attempt_observations (id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE admissions (
      owner TEXT NOT NULL, conversation_id TEXT NOT NULL, intent TEXT NOT NULL,
      request_key TEXT NOT NULL, fingerprint TEXT NOT NULL, resource_id TEXT NOT NULL,
      response TEXT NOT NULL, created INTEGER NOT NULL,
      PRIMARY KEY(owner,conversation_id,intent,request_key));
CREATE TABLE artifacts (id TEXT PRIMARY KEY, sha256 TEXT NOT NULL, size INTEGER NOT NULL, mime TEXT NOT NULL, filename TEXT NOT NULL, owner TEXT NOT NULL, conversation_id TEXT, session_id TEXT, actor_id TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE attempt_observations (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE conversations (id TEXT PRIMARY KEY, owner TEXT NOT NULL, chat_id TEXT NOT NULL, message_thread_id INTEGER, kind TEXT NOT NULL, title TEXT, state TEXT NOT NULL DEFAULT 'active', settings TEXT NOT NULL DEFAULT '{}', session_id TEXT NOT NULL, UNIQUE(chat_id,message_thread_id));
CREATE TABLE history (id INTEGER PRIMARY KEY, user TEXT, role TEXT, text TEXT, created INTEGER, conversation_id TEXT, session_id TEXT, actor_id TEXT);
CREATE TABLE history_origins (history_id INTEGER PRIMARY KEY, owner TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('direct_owner','owner_group','forwarded','bot','attachment','event','other')));
CREATE TABLE inputs (id INTEGER PRIMARY KEY, user TEXT, payload TEXT, state TEXT DEFAULT 'pending', created INTEGER, conversation_id TEXT, session_id TEXT, actor_id TEXT);
CREATE TABLE jobs (id TEXT PRIMARY KEY, user TEXT, prompt TEXT, profile TEXT, state TEXT, result TEXT, created INTEGER, thread TEXT, conversation_id TEXT, session_id TEXT, actor_id TEXT, goal_outcome TEXT, schedule_id TEXT, scheduled_for INTEGER);
CREATE TABLE learning_events(id INTEGER PRIMARY KEY,user TEXT NOT NULL,source TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(user,source));
CREATE TABLE learning_outcomes(id TEXT PRIMARY KEY,user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,created INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE learning_records(user TEXT NOT NULL,key TEXT NOT NULL,payload TEXT NOT NULL,revision INTEGER NOT NULL,updated INTEGER NOT NULL,offered INTEGER,outbox_id INTEGER,PRIMARY KEY(user,key));
CREATE TABLE learning_reviews(id TEXT PRIMARY KEY,user TEXT NOT NULL,created INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE learning_trial_bindings(user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,evidence_cursor INTEGER NOT NULL,PRIMARY KEY(user,key,revision));
CREATE TABLE learning_versions(user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user,key,revision));
CREATE TABLE main_sessions (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, thread TEXT, created INTEGER NOT NULL);
CREATE TABLE memories(id INTEGER PRIMARY KEY AUTOINCREMENT,user TEXT NOT NULL,key TEXT NOT NULL,category TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,certainty TEXT NOT NULL,sources TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,seq INTEGER NOT NULL,origin TEXT NOT NULL,exported_seq INTEGER NOT NULL DEFAULT 0, observed_at TEXT, valid_from TEXT, valid_to TEXT, review_after TEXT, entity TEXT, project TEXT,UNIQUE(user,key));
CREATE TABLE memory_blocked_history(user TEXT NOT NULL,history_id INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user,history_id));
CREATE VIRTUAL TABLE memory_fts USING fts5(title,content,tokenize='unicode61');
CREATE TABLE memory_invalidations(user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,source TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user,key,revision,source,reason));
CREATE TABLE memory_review_exports(user TEXT NOT NULL,key TEXT NOT NULL,hash TEXT NOT NULL,PRIMARY KEY(user,key));
CREATE TABLE memory_sources(user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,source TEXT NOT NULL,PRIMARY KEY(user,key,revision,source));
CREATE TABLE memory_tombstones(user TEXT NOT NULL,key TEXT NOT NULL,blocked_history TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user,key));
CREATE TABLE memory_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,user TEXT NOT NULL,key TEXT NOT NULL,revision INTEGER NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE observation_links (run_id TEXT PRIMARY KEY,conversation_id TEXT,parent_run_id TEXT,job_id TEXT);
CREATE TABLE outbox (id INTEGER PRIMARY KEY, user TEXT, payload TEXT, state TEXT DEFAULT 'pending', attempts INTEGER DEFAULT 0, due INTEGER, proactive INTEGER DEFAULT 0, conversation_id TEXT, session_id TEXT, actor_id TEXT, artifact_id TEXT REFERENCES artifacts(id), legacy_state TEXT);
CREATE TABLE run_observations (id TEXT PRIMARY KEY,terminal TEXT,payload TEXT NOT NULL);
CREATE TABLE schedule_goal_receipts (schedule_id TEXT PRIMARY KEY, job_id TEXT NOT NULL, goal_hash TEXT NOT NULL, owner TEXT NOT NULL, conversation_id TEXT NOT NULL, evidence_id INTEGER NOT NULL, authority TEXT NOT NULL CHECK(authority='explicit_owner'), recorded_at INTEGER NOT NULL);
CREATE TABLE schedule_occurrences (schedule_id TEXT NOT NULL, scheduled_for INTEGER NOT NULL, disposition TEXT NOT NULL, job_id TEXT, recorded_at INTEGER NOT NULL, conversation_id TEXT, session_id TEXT, actor_id TEXT, skipped_before INTEGER, PRIMARY KEY(schedule_id,scheduled_for));
CREATE TABLE schedules (id TEXT PRIMARY KEY, user TEXT, kind TEXT, prompt TEXT, cron TEXT, timezone TEXT, due INTEGER, enabled INTEGER DEFAULT 1, unique_key TEXT UNIQUE, conversation_id TEXT, session_id TEXT, actor_id TEXT, overlap_policy TEXT, misfire_policy TEXT, catch_up_limit INTEGER, misfire_grace_seconds INTEGER, objective TEXT, done_condition TEXT, deadline INTEGER, max_runs INTEGER, runs INTEGER NOT NULL DEFAULT 0, goal_state TEXT NOT NULL DEFAULT 'active');
CREATE TABLE usage_baselines (thread_key TEXT PRIMARY KEY,usage TEXT,valid INTEGER NOT NULL,active INTEGER NOT NULL,epoch TEXT NOT NULL,generation INTEGER NOT NULL);
CREATE UNIQUE INDEX conversations_transport ON conversations(chat_id,coalesce(message_thread_id,0));
CREATE TRIGGER history_conversation AFTER INSERT ON history BEGIN UPDATE history SET conversation_id=coalesce(NEW.conversation_id,(SELECT value FROM meta WHERE key='conversation-id')),session_id=coalesce(NEW.session_id,(SELECT value FROM meta WHERE key='main-session')),actor_id=coalesce(NEW.actor_id,NEW.user) WHERE rowid=NEW.rowid; END;
CREATE INDEX history_conversation_order ON history(conversation_id,user,id);
CREATE INDEX history_user_order ON history(user,id);
CREATE TRIGGER inputs_conversation AFTER INSERT ON inputs BEGIN UPDATE inputs SET conversation_id=coalesce(NEW.conversation_id,(SELECT value FROM meta WHERE key='conversation-id')),session_id=coalesce(NEW.session_id,(SELECT value FROM meta WHERE key='main-session')),actor_id=coalesce(NEW.actor_id,NEW.user) WHERE rowid=NEW.rowid; END;
CREATE INDEX inputs_conversation_pending ON inputs(conversation_id,created,id) WHERE state='pending';
CREATE INDEX inputs_pending_order ON inputs(created,id) WHERE state='pending';
CREATE TRIGGER jobs_conversation AFTER INSERT ON jobs BEGIN UPDATE jobs SET conversation_id=coalesce(NEW.conversation_id,(SELECT value FROM meta WHERE key='conversation-id')),session_id=coalesce(NEW.session_id,(SELECT value FROM meta WHERE key='main-session')),actor_id=coalesce(NEW.actor_id,NEW.user) WHERE rowid=NEW.rowid; END;
CREATE INDEX jobs_conversation_state ON jobs(conversation_id,state,created);
CREATE UNIQUE INDEX jobs_schedule_occurrence ON jobs(schedule_id,scheduled_for) WHERE schedule_id IS NOT NULL;
CREATE INDEX jobs_state_order ON jobs(state,created);
CREATE INDEX jobs_user_order ON jobs(user,created DESC);
CREATE INDEX learning_events_owner ON learning_events(user,id);
CREATE TRIGGER learning_history AFTER INSERT ON history WHEN NEW.role IN ('user','assistant','event') BEGIN
        INSERT OR IGNORE INTO learning_events(user,source,created) VALUES(NEW.user,'history:'||NEW.id,NEW.created); END;
CREATE TRIGGER learning_jobs AFTER UPDATE OF state ON jobs WHEN NEW.state IN ('completed','failed','cancelled','interrupted') AND NEW.prompt NOT LIKE '[LEARNING]%' AND NEW.prompt NOT LIKE '[MEMORY]%' AND NEW.prompt NOT LIKE '[REFLECTION]%' AND NEW.prompt NOT LIKE '[CLEANUP]%' BEGIN
        INSERT OR IGNORE INTO learning_events(user,source,created) VALUES(NEW.user,'job:'||NEW.id,NEW.created); END;
CREATE INDEX learning_outcomes_candidate ON learning_outcomes(user,key,revision);
CREATE INDEX memories_user_entity ON memories(user,entity);
CREATE INDEX memories_user_project ON memories(user,project);
CREATE INDEX memories_user_seq ON memories(user,seq);
CREATE TRIGGER memory_current_sources AFTER INSERT ON memories BEGIN
CREATE INDEX memory_sources_lookup ON memory_sources(user,source);
CREATE TRIGGER memory_updated_sources AFTER UPDATE OF sources,revision ON memories WHEN NEW.status!='forgotten' BEGIN
CREATE TRIGGER memory_version_sources AFTER INSERT ON memory_versions BEGIN
        INSERT OR IGNORE INTO memory_sources SELECT NEW.user,NEW.key,NEW.revision,value FROM json_each(NEW.payload,'$.sources'); END;
CREATE TRIGGER outbox_conversation AFTER INSERT ON outbox BEGIN UPDATE outbox SET conversation_id=coalesce(NEW.conversation_id,(SELECT value FROM meta WHERE key='conversation-id')),session_id=coalesce(NEW.session_id,(SELECT value FROM meta WHERE key='main-session')),actor_id=coalesce(NEW.actor_id,NEW.user) WHERE rowid=NEW.rowid; END;
CREATE INDEX outbox_conversation_pending ON outbox(conversation_id,id) WHERE state='pending';
CREATE INDEX outbox_pending_order ON outbox(id) WHERE state='pending';
CREATE TRIGGER schedules_conversation AFTER INSERT ON schedules BEGIN UPDATE schedules SET conversation_id=coalesce(NEW.conversation_id,(SELECT value FROM meta WHERE key='conversation-id')),session_id=coalesce(NEW.session_id,(SELECT value FROM meta WHERE key='main-session')),actor_id=coalesce(NEW.actor_id,NEW.user) WHERE rowid=NEW.rowid; END;
CREATE INDEX schedules_conversation_due ON schedules(conversation_id,due) WHERE enabled=1;
CREATE INDEX schedules_due ON schedules(due) WHERE enabled=1;
